// Translation engine (no React, no DOM: also used by scripts/i18n-check.ts).
//
// Catalogs are keyed by the English text.
// * ui:     strings written in the dashboard code, used through t("...") / <T k="...">.
//           Named parameters: "Latest model run {when}".
// * server: sentences generated by the backend (severity explanations, model
//           notes, alerts, report lines). Keys are templates whose numbered
//           placeholders match parts of the English sentence:
//             {n1} a number        -> reformatted for the language
//             {d1} an ISO date     -> reformatted for the language
//             {t1} a nested phrase -> translated recursively
//             {s1} a name or code  -> kept, except known country names
//           A translation must use exactly the placeholders of its key.
// * places: names of priority countries by ISO3 code.
// A sentence without a matching entry is shown in English.

export interface Catalog {
  _meta?: { language: string; name: string; status: string; note?: string };
  ui?: Record<string, string>;
  server?: Record<string, string>;
  places?: Record<string, string>;
}

const PLACEHOLDER = /\{([ndts])(\d+)\}/g;
const PATTERNS: Record<string, string> = {
  n: "(-?\\d[\\d,]*(?:\\.\\d+)?)",
  d: "(\\d{4}-\\d{2}-\\d{2})",
  t: "(.+?)",
  s: "(.+?)",
};

export function placeholders(template: string): string[] {
  return [...template.matchAll(PLACEHOLDER)].map((m) => m[1] + m[2]).sort();
}

interface Compiled {
  key: string;
  re: RegExp;
  names: string[];
  weight: number;
}

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function compileTemplate(key: string): Compiled | null {
  const names: string[] = [];
  let re = "^";
  let last = 0;
  for (const m of key.matchAll(PLACEHOLDER)) {
    re += escapeRe(key.slice(last, m.index));
    re += PATTERNS[m[1]];
    names.push(m[1] + m[2]);
    last = (m.index ?? 0) + m[0].length;
  }
  if (!names.length) return null; // plain sentences are matched exactly
  re += escapeRe(key.slice(last)) + "$";
  return { key, re: new RegExp(re, "s"), names, weight: key.replace(PLACEHOLDER, "").length };
}

export interface Formatters {
  number: (raw: string) => string;
  date: (iso: string) => string;
  place: (name: string) => string;
}

export class Translator {
  readonly ui: Record<string, string>;
  readonly server: Record<string, string>;
  private readonly templates: Compiled[];
  private readonly fmt: Formatters;

  constructor(catalog: Catalog, fmt: Formatters) {
    this.fmt = fmt;
    this.ui = catalog.ui ?? {};
    this.server = catalog.server ?? {};
    this.templates = Object.keys(this.server)
      .map(compileTemplate)
      .filter((c): c is Compiled => c !== null)
      .sort((a, b) => b.weight - a.weight); // most specific first
  }

  /** Dashboard text, with named parameters. */
  t(en: string, params?: Record<string, string | number>): string {
    const s = this.ui[en] ?? en;
    return params ? s.replace(/\{(\w+)\}/g, (m, k: string) => (k in params ? String(params[k]) : m)) : s;
  }

  /** Backend-generated text; returns null when no catalog entry matches. */
  match(text: string, depth = 0): string | null {
    if (!text || depth > 4) return null;
    const exact = this.server[text];
    if (exact !== undefined) return exact;
    for (const c of this.templates) {
      const m = c.re.exec(text);
      if (!m) continue;
      const values: Record<string, string> = {};
      c.names.forEach((name, i) => {
        const raw = m[i + 1];
        const kind = name[0];
        values[name] =
          kind === "n" ? this.fmt.number(raw)
          : kind === "d" ? this.fmt.date(raw)
          : kind === "t" ? (this.match(raw, depth + 1) ?? this.fmt.place(raw))
          : this.fmt.place(raw);
      });
      return this.server[c.key].replace(PLACEHOLDER, (ph, k: string, n: string) => values[k + n] ?? ph);
    }
    return null;
  }

  tx(text: string | null | undefined): string {
    if (!text) return text ?? "";
    return this.match(text) ?? this.fmt.place(text); // a bare country name is localized too
  }
}

/** Parse a number as written by the backend ("1,404", "0.90") into a value and its decimals. */
export function parseNumber(raw: string): { value: number; decimals: number } {
  const clean = raw.replace(/,/g, "");
  const dot = clean.indexOf(".");
  return { value: Number(clean), decimals: dot === -1 ? 0 : clean.length - dot - 1 };
}
